const input=$json.body??$json;
const s=v=>String(v??'').trim();
const audit=input.audit??input;
const identity=audit.identity??input.identity??{};
const leadId=s(identity.lead_id);
const propertyId=s(identity.property_id);
const dealId=s(identity.deal_id);
const id=s(dealId||propertyId||leadId);
const requestId=s(audit.request_id??input.request_id);
const auditId=s(audit.audit_id)||('underwriting-decision:'+(id||'unknown')+':'+(requestId||'unknown')+':v1');
const decision=audit.decision??input.decision??{};
const evidenceQuality=audit.evidence_quality??input.evidence_quality??{};
const risks=decision.risks??input.risks??[];
const assumptions=decision.assumptions??input.assumptions??{};
const recommendedOffer=decision.recommended_offer??null;
const status=s(decision.status??input.status).toLowerCase();
const missing=[];
if(!leadId)missing.push('lead_id');
if(!recommendedOffer)missing.push('recommended_offer');
if(!status)missing.push('decision_status');
const activityId='underwriting-decision:'+auditId;
const notes=[
'Underwriting decision persisted by Wholesaling OS.',
'Decision status: '+status,
'Recommended offer/MAO: '+String(recommendedOffer??'not supplied'),
'Evidence confidence: '+String(evidenceQuality.overall_score??evidenceQuality.score??'not supplied'),
'Risks: '+JSON.stringify(risks),
'Assumptions: '+JSON.stringify(assumptions),
'Audit ID: '+auditId
].join('\n');
const activity={activity_type:'underwriting_decision',subject:'AI underwriting decision '+(status||'recorded'),body:notes,lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null,external_id:activityId,external_source:'wholesaling-os-underwriting',metadata:{audit_id:auditId,request_id:requestId||null,recommended_offer:recommendedOffer,evidence_quality:evidenceQuality,risks,assumptions,decision_status:status}};
return[{json:{ok:missing.length===0,status:missing.length?'persistence_blocked':'persistence_ready',audit_id:auditId,request_id:requestId||null,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},decision:{status,recommended_offer:recommendedOffer,evidence_quality:evidenceQuality,risks,assumptions},crm_activity:activity,missing_requirements:missing,next_workflow:missing.length?'human_review':'crm_persist'}}];
